#pragma once
bool key(VirtualKey k){if(!kb)return false;if(k>=VK_a&&k<=VK_z)return kb->isVKDown(k)||kb->isVKDown(static_cast<VirtualKey>(VK_A+k-VK_a));if(k==VK_RETURN)return kb->isVKDown(VK_RETURN)||kb->isVKDown(VK_KP_ENTER);return kb->isVKDown(k);}
VirtualKey watched[16];bool wasDown[16]={};int watchCount=0;bool helpOpen=false;
bool pressed(VirtualKey k){int i=0;while(i<watchCount&&watched[i]!=k)++i;if(i==watchCount){if(watchCount==16)return false;watched[watchCount++]=k;}bool down=key(k),out=down&&!wasDown[i];wasDown[i]=down;return out;}
Input controls(){bool enter=pressed(VK_RETURN),esc=pressed(VK_ESCAPE),pause=pressed(VK_p),mute=pressed(VK_m),gear=pressed(VK_z),automatic=pressed(VK_a),help=pressed(VK_i),detail=pressed(VK_f),view=pressed(VK_v),leftChoice=pressed(VK_LEFT),rightChoice=pressed(VK_RIGHT),upChoice=pressed(VK_UP),downChoice=pressed(VK_DOWN);if(view){wideView=!wideView;refreshMargins=true;}if(race.screen==TITLE&&(leftChoice||rightChoice))stageChoice=(stageChoice+(rightChoice?1:STAGES-1))%STAGES;if(detail)liteMode=!liteMode;if(mute)race.mute=!race.mute;if(helpOpen){if(help||esc||enter)helpOpen=false;return {}; }if(help){helpOpen=true;return {};}
 if(race.screen==CAR_SELECT){if(leftChoice||rightChoice||upChoice||downChoice){carChoice=(carChoice+(rightChoice||downChoice?1:CAR_COUNT-1))%CAR_COUNT;loadRecord();}if(enter)startRace();if(esc)race.screen=TITLE;}
 else if(race.screen==TITLE||race.screen==GAMEOVER||race.screen==FINISHED){if(enter)race.screen=CAR_SELECT;if(esc)race.screen=TITLE;}else{if(esc)race.screen=TITLE;if(pause)race.paused=!race.paused;if(gear){race.automatic=false;race.high=!race.high;}if(automatic)race.automatic=true;}
 return {key(VK_UP)||key(VK_SPACE),key(VK_DOWN),key(VK_LEFT),key(VK_RIGHT)};}
void renderHelp(){hideActors();rect(0,0,639,199,192);centred(13,"BX RUN / GUIA DE CONDUCAO",rgb(3,3,1));const char*lines[]={"CIMA ou ESPACO: acelerar / BAIXO: travar","ESQUERDA / DIREITA: virar","A caixa e automatica ao iniciar a corrida.","Z: selecionar LOW/HI manualmente / A: voltar a automatico","P: pausa M: som F: detalhe V: janela/panoramico ESC: menu","Seis etapas e cinco Citroen; mapa a esquerda.","Checkpoints: +25 s; 2CV recebe +33 s.","A relva faz perder velocidade; evita bater no transito.","O recorde fica guardado no ESP32.","Titulo: etapa inicial. Depois ENTER para escolher o carro.","I, ENTER ou ESC: voltar"};for(int i=0;i<11;++i)centred(38+i*13,lines[i],i==10?rgb(1,3,3):255);}
